from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up.
prime_hub = PrimeHub()
back_motor = Motor(Port.A, Direction.CLOCKWISE)
Left_wheel = Motor(Port.B, Direction.COUNTERCLOCKWISE)
front_motor = Motor(Port.D, Direction.CLOCKWISE)
right_wheel = Motor(Port.F, Direction.CLOCKWISE)
drive_base = DriveBase(Left_wheel, right_wheel, 62, 187)

def Exploding_seeds():
    drive_base.use_gyro(True)
    drive_base.settings(straight_speed=1000)
    drive_base.straight(200)
    drive_base.turn(90)
    drive_base.straight(60)
    drive_base.turn(-45)
    front_motor.run_angle(400, 35)
    drive_base.straight(160)
    front_motor.run_angle(500, 40)
    drive_base.straight(-30)
    front_motor.run_angle(500, 22)
    drive_base.settings(straight_speed=200)
    drive_base.straight(-15, then=Stop.NONE)
    front_motor.run_angle(900, -40)
    drive_base.straight(-15)
    front_motor.run_angle(900, -40)
    drive_base.straight(-50, then=Stop.NONE)
    back_motor.run_angle(500, -8)


# The main program starts here.
drive_base.use_gyro(True)
front_motor.run_angle(500, 40)
drive_base.straight(150)
drive_base.turn(-70)
drive_base.straight(560)
drive_base.turn(70)
drive_base.straight(250)
drive_base.turn(43)
front_motor.run_angle(500, -39)
drive_base.settings(straight_speed=155)
drive_base.straight(258)
drive_base.straight(-30)
drive_base.turn(90)
drive_base.settings(straight_speed=3000)
drive_base.straight(1000)
